function gameOf(a){
  const g = store.get(gameKey(a)), o = isObj(g) ? g : {}, n = (v, lo, hi, d) => Number.isInteger(v) && v >= lo && v <= hi ? v : d;
  const two = (x, hi) => ({ mine:n((x || {}).mine, 0, hi, 0), opp:n((x || {}).opp, 0, hi, 0) });
  return { round:n(o.round, 1, 5, 1), half:n(o.half, 0, 1, 0), first:o.first === 'opp' ? 'opp' : 'mine', ph:hasOwn(PHASE_NAME, o.ph) ? o.ph : 'command',
    cp:two(o.cp, 99), vp:two(o.vp, 999), picks:isObj(o.picks) ? o.picks : {} };
}

function newGame(a){
  const o = gameOwner(a), opp = oppOf(o);
  const keys = [gameKey(a), 'wh-used-' + o.id].concat(opp && opp !== o ? ['wh-used-' + opp.id] : []);
  const was = keys.map(k => [k, store.get(k, null)]);
  store.set(keys[0], null); for(const k of keys.slice(1)) store.set(k, []);
  return () => { for(const [k, v] of was) store.set(k, v); };
}

function gcLasts(t){
  if(/\buntil the end of the battle(?! round)|\bfor the coming battle\b/i.test(t)) return 'battle';
  if(/\buntil the (?:end of the battle round|start of the next battle round|start of your next command phase)\b/i.test(t)) return 'round';
  if(/\bremains in that [a-z]+ until it enters a different one\b/i.test(t)) return 'kept';
  return '';
}

function gcParts(text){
  const out = [];
  for(const raw of String(text || '').split('\n')){
    const l = raw.trim(), m = /^\*\*([^*]+?):\*\*\s*/.exec(l);
    if(m) out.push({ name:m[1], text:l });
    else if(out.length && /^- /.test(l)) out[out.length - 1].text += '\n' + l;
  }
  return out;
}

const gcBullets = text => String(text || '').split('\n').map(l => l.trim()).filter(l => /^- /.test(l)).map(l => {
  const b = /^- \*\*([^*]+?):\*\*/.exec(l), s = /^- ([^.:]+)[.:]/.exec(l);
  return { name:b ? b[1] : s ? s[1] : l.slice(2), text:l.slice(2) }; });

function gcTable(table){
  const rows = table.map(([k, v]) => { const d = /^(\S+) (\d[–-]\d) · (.*)$/.exec(k), p = String(k).split(' · ');
    return d ? { group:d[1], name:d[2], title:d[3], text:v, row:k } : { group:'', name:p[0], title:p.slice(1).join(' · '), text:v, row:k }; });
  return [...new Set(rows.map(r => r.group))].map(g => ({ name:g, opts:rows.filter(r => r.group === g) }));
}

function gcOptions(x, u){
  const t = x.text || '', sel = [...t.matchAll(GC_SEL)];
  if(!sel.length) return null;
  if(x.table && x.table.length){
    const groups = gcTable(x.table);
    if(sel.some(m => /\bbelow\b/i.test(m[2]) || groups.some(g => g.name && new RegExp('^\\s*' + g.name + '\\b', 'i').test(m[2])))) return groups;
  }
  for(const m of sel){
    const sec = /^\s*(?:of the abilities in the )?(.+?) (?:section|ability)\b/i.exec(m[2]);
    if(sec && u){
      const N = sec[1].replace(/\*\*/g, '').trim();
      const whos = u.abilities.filter(ab => ab.who && (ab.who === N || ab.who.startsWith(N + ':')));
      if(whos.length) return [{ name:'', opts:whos.map(ab => ({ name:ab.name, text:ab.text, ab })) }];
      const host = u.abilities.find(ab => ab.name === N), parts = host ? gcParts(host.text) : [];
      if(parts.length > 1) return [{ name:'', opts:parts, host }];
    }
    if(/\b(?:of the following|listed below|from those listed below)\b/i.test(m[2])){ const b = gcBullets(t); if(b.length > 1) return [{ name:'', opts:b }]; }
  }
  return null;
}

const gcWhen = (x, at) => {
  const t = String(x.text || '').replace(/\*\*/g, ''), s0 = t.lastIndexOf('.', at) + 1, sen = t.slice(s0).trim();
  const own = /^(?:if your army faction is [^,]+, )?((?:at the (?:start|end) of|in) [^,]+),/i.exec(sen);
  const any = /\b(at the (?:start|end) of (?:the |your |each |every )?[^,.]+|in your [a-z ]+? phase)/i.exec(t);
  const w = own ? own[1] : any ? any[1] : x.at || '';
  return w ? w.charAt(0).toUpperCase() + w.slice(1) : '';
};

function gameChoices(a){
  return inArmy(a, () => {
    const f = faction(), out = [];
    const add = (x, key, src, link, u, i) => {
      const lasts = gcLasts(x.text || ''), groups = lasts && gcOptions(x, u);
      if(!groups) return;
      const m = [...String(x.text || '').matchAll(GC_SEL)][0];
      out.push({ key, name:x.name, src, link, lasts, groups, unit:u || null, copy:i || 0, when:gcWhen(x, m.index),
        max:{ 'up to two':2, 'up to three':3 }[m[1].toLowerCase()] || 1, rolled:/\brandomly select\b/i.test(x.text),
        state:(/\byour army becomes ([A-Z][a-z]+)\b/.exec(x.text) || [])[1] || '', once:/\bselect each of these [a-z ]+ once per battle\b/i.test(x.text), rule:x });
    };
    for(const r of f.armyRules) if(!inertRule(r.name)) add(r, 'r:' + r.name, f.name + ' army rule', ['rule', r.name]);
    for(const d of detachments()) if(d.rule && army().units.some(u => matches(d.rule.needs, u))) add(d.rule, 'r:' + d.rule.name, d.name + ' detachment rule', ['rule', d.rule.name]);
    for(const u of army().units) for(const ab of u.abilities){
      if(naReason(ab)) continue;
      const c = u.copies || 1;
      for(let i = 0; i < c; i++) add(ab, copyKey(ab, u, i), gUnitName(u) + (c > 1 ? ' · Unit ' + (i + 1) : ''), ['ability', abilityKey(ab)], u, i);
    }
    // an option of another choice of the same unit (a Crimson King ability, Wrathful Presence: pick one) is not a choice itself
    return out.filter(c => !c.unit || !out.some(o => o !== c && o.unit === c.unit && o.groups.some(gr => gr.opts.some(x => x.ab === c.rule))));
  });
}

function gcPick(c, g, side){
  const all = ((g.picks[side] || {})[c.key]) || {};
  if(c.lasts !== 'kept') return { v:all[gcRound(c, g)] || {}, since:null, all };
  for(let r = g.round; r >= 1; r--) if(isObj(all[r]) && Object.keys(all[r]).length) return { v:all[r], since:r === g.round ? null : r, all };
  return { v:{}, since:null, all };
}

function gcTargets(text, opp){
  if(!opp) return null;
  const t = String(text || '').replace(/\*\*/g, ''), m = /\bselect one (?:([A-Z][A-Z -]*[A-Z]) )?(?:model|unit) (?:in|from) your opponent[’']s army\b|\bselect one (enemy) unit\b/i.exec(t);
  if(!m) return null;
  const kw = m[1] && m[1] === m[1].toUpperCase() ? m[1] : '';
  return inArmy(opp, () => opp.units.filter(u => !kw || hasKw(u, kw)).map(u => ({ id:u.id, name:shortName(u) })));
}

function gStep(x, ph){
  if(/^start of the battle round$/i.test(x.at || '')) return 'round';
  if(/^end of (your opponent[’']s|your) turn$/i.test(x.at || '')) return 'turnEnd';
  const m = G_STEP.exec(gText(x));
  if(!m) return 'during';
  const se = m[1].toLowerCase();
  if(m[3]) return m[3].toLowerCase() === ph ? se : 'during';
  const w = m[4].toLowerCase();
  if(w === 'battle round' || w === 'first battle round') return se === 'start' ? (w === 'first battle round' ? 'first' : 'round') : 'roundEnd';
  if(w === 'battle') return se === 'start' ? 'battle' : 'during';
  if(w === 'turn') return se === 'start' ? 'turnStart' : 'turnEnd';
  return se;   // "at the start of any phase"
}

function gUntagged(x){
  const m = G_STEP.exec(gText(x));
  if(!m) return null;
  const who = /opponent/i.test(m[2] || m[0]) ? 'opp' : /\byour\b/i.test(m[2] || m[0]) ? 'your' : 'either';
  if(m[3]) return { ph:[m[3].toLowerCase()], turn:who };
  if(/^turn$/i.test(m[4])) return { ph:[m[1].toLowerCase() === 'start' ? 'command' : 'fight'], turn:who };
  return null;
}

function gamePhase(a, ph, turn, opts){
  opts = opts || {};
  return inArmy(a, () => {
    const f = faction(), out = [];
    const tags = x => phasesOf(x).length ? x : gUntagged(x) || x;
    const on = x => { const t = tags(x); return phasesOf(t).includes(ph) && (phTurn(t, ph) === 'either' || phTurn(t, ph) === turn); };
    const every = x => phasesOf(x).length === PHASES.length && !(x.remind || []).some(on);
    // where it goes in this phase (null: not here)
    const place = (x, hit) => {
      const s = gStep(x, ph);
      if(s === 'round' || s === 'first' || s === 'battle'){
        if(opts.start && (s === 'round' || opts.round === 1)) return s;
        if(!hit) return null;
        if(every(x)) return 'any';
        return ph !== 'command' || /\bcommand phase\b/i.test(gText(x).replace(/^[^.]*\./, '')) ? 'during' : null;
      }
      return hit ? (every(x) ? 'any' : s) : null;
    };
    const rule = (r, src) => { const st = place(r, on(r) || (r.remind || []).some(on)); if(st) out.push({ kind:'rule', name:r.name, src, x:r, step:st }); };
    for(const r of f.armyRules) if(!inertRule(r.name)) rule(r, f.name + ' army rule');
    for(const d of detachments()) if(d.rule && army().units.some(u => matches(d.rule.needs, u))) rule(d.rule, d.name + ' detachment rule');
    const abs = new Map();
    for(const u of army().units) for(const ab of u.abilities){
      if(naReason(ab) || ab.damaged) continue;
      const st = place(ab, on(ab));
      if(!st) continue;
      const k = abilityKey(ab);
      if(!abs.has(k)) abs.set(k, { kind:'ability', name:ab.name, ab, key:k, units:[], step:st });
      abs.get(k).units.push(u);
    }
    for(const e of abs.values()) out.push(Object.assign(e, { src:labelList(e.units) }));
    for(const s of allStratagems()){ const st = place({ when:s.when, phases:s.phases, turn:s.turn, turns:s.turns }, on(s)); if(st) out.push({ kind:'strat', name:s.name, s, src:s.src, usable:eligible(s).length > 0, step:st }); }
    for(const e of out) e.any = e.step === 'any';
    return out;
  });
}

function gPhaseHtml(L, g, ph, turn, picked, opts, pickOf){
  const firstTurn = g.half === 0, lastTurn = g.half === 1, start = ph === 'command' && firstTurn;
  const items = gamePhase(L, ph, turn, { start, round:g.round }), S = D.game.steps, st = S[ph];
  const groups = [];
  if(start && g.round === 1) groups.push(['Start of the battle', items.filter(e => e.step === 'battle')]);
  if(start) groups.push([gStepName(S.round[0]), items.filter(e => e.step === 'round' || e.step === 'first')]);
  groups.push([gStepName(st[0]), items.filter(e => e.step === 'start' || (e.step === 'turnStart' && ph === 'command'))]);
  if(ph === 'command' && opts.cp) groups.push([gStepName([D.game.cp[0].num, D.game.cp[0].title]), [], rt(D.game.cp[0].text)]);   // 08.02, after 08.01
  groups.push([st.slice(1, -1).map(gStepName).join(' · ') || 'During the phase', items.filter(e => e.step === 'during' || (e.step === 'turnStart' && ph !== 'command') || (e.step === 'turnEnd' && ph !== 'fight') || (e.step === 'roundEnd' && !(ph === 'fight' && lastTurn)))]);
  groups.push([gStepName(st[st.length - 1]), items.filter(e => e.step === 'end')]);
  if(ph === 'fight') groups.push(['End of the turn', items.filter(e => e.step === 'turnEnd')]);
  if(ph === 'fight' && lastTurn) groups.push([gStepName(S.round[1]), items.filter(e => e.step === 'roundEnd')]);
  const sort = list => list.slice().sort((x, y) => (x.kind === 'strat') - (y.kind === 'strat') || (x.kind === 'strat' && y.kind === 'strat' ? (y.usable - x.usable) : 0));
  let h = groups.filter(([, list, extra]) => list.length || extra).map(([title, list, extra]) => '<div class="gph"><p class="gpt">' + title + '</p>' + (extra || '') + gRows(L, sort(list), picked, pickOf) + '</div>').join('');
  const any = items.filter(e => e.any);
  if(any.length) h += '<details class="gx"' + (opts.fold && opts.fold.any ? ' open' : '') + ' data-gfold="any"><summary><span>Any phase</span><span class="c">' + any.length + '</span>' + chev + '</summary>' + gRows(L, sort(any), picked, pickOf) + '</details>';
  return h || '<p class="note">Nothing of this list is tagged for this phase.</p>';
}

function gRows(L, items, picked, pickOf){
  const own = L.id === cur.army;
  const now = e => { const n = pickOf ? pickOf(e) : ''; return n ? '<span class="gpn">Picked: ' + esc(n) + '</span>' : ''; };
  return items.map(e => {
    if(e.kind === 'strat'){ const s = e.s, pb = own && perBattle(s);
      return '<div class="gr gs' + (e.usable ? '' : ' none') + '"><span class="cp' + (s.cp >= 2 ? ' hot' : '') + '">' + esc(s.cp) + '<small>CP</small></span><span class="grb">' + gLink(L, 'strat', s.id, s.name) +
        (s.gist ? '<span class="sg">' + esc(s.gist) + '</span>' : '') + (e.usable ? '' : '<span class="from">' + esc(inArmy(L, () => usersLine(s))) + '</span>') + (pb ? ticks('s:' + s.id, pb.n, '', s.name) : '') + '</span></div>'; }
    if(e.kind === 'rule'){ const pb = own && perBattle(e.x, true);
      return '<div class="gr"><span class="grb">' + gLink(L, 'rule', e.name, e.name) + ' <span class="from">· ' + esc(e.src) + '</span>' + now(e) + (pb ? ticks('r:' + e.name, pb.n, '', e.name) : '') + '</span></div>'; }
    const p = picked ? picked(e.ab, e.units) : null, pb = own && perBattle(e.ab) && !naReason(e.ab);
    const who = e.ab.who && (p !== null || !e.src.includes(e.ab.who.replace(/: pick one$/, ''))) ? e.ab.who.replace(/: pick one$/, '') : '';
    const boxes = !pb ? '' : perBattle(e.ab).army ? abilityTicks(e.ab, e.units[0]) : e.units.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) =>
      ticks(copyKey(e.ab, u, i), perBattle(e.ab).n, e.units.length > 1 || (u.copies || 1) > 1 ? shortName(u) + ((u.copies || 1) > 1 ? ' ' + (i + 1) : '') : '', e.ab.name))).join('');
    return '<div class="gr' + (p === false ? ' none' : '') + '"><span class="grb">' + gLink(L, 'ability', e.key, e.ab.name) + ' <span class="from">· ' + esc(e.src) + '</span>' +
      (who ? ' <span class="tg m">' + esc(who) + (p === true ? ': picked' : p === false ? ': not picked' : '') + '</span>' : '') + now(e) + (boxes ? '<span class="gtk">' + boxes + '</span>' : '') + '</span></div>';
  }).join('');
}

const G_CP = /[^.
]* (?:gain|gains) [^.
]*(?:\dCP| CP |Command Points?)[^.
]*\.?/i;

function gameCpRules(L){
  const out = inArmy(L, () => {
    const out = [], f = faction(), line = t => String(t || '').split('\n').filter(l => !/^\*/.test(l.trim())).map(l => (G_CP.exec(l) || [])[0]).find(Boolean);
    for(const r of f.armyRules){ const s = !inertRule(r.name) && line(r.text); if(s) out.push({ t:'rule', v:r.name, name:r.name, src:f.name + ' army rule', s:s.trim() }); }
    for(const d of detachments()){ const s = d.rule && line(d.rule.text); if(s) out.push({ t:'rule', v:d.rule.name, name:d.rule.name, src:d.name, s:s.trim() }); }
    const by = new Map();
    for(const u of army().units) for(const ab of u.abilities){ const s = !naReason(ab) && line(ab.text); if(!s) continue;
      const k = abilityKey(ab); if(!by.has(k)) by.set(k, { t:'ability', v:k, name:ab.name, s:s.trim(), units:[] }); by.get(k).units.push(u); }
    for(const e of by.values()) out.push(Object.assign(e, { src:labelList(e.units) }));
    return out;
  });
  return out.map(e => Object.assign(e, { link:gLink(L, e.t, e.v, e.name) }));   // linked from the list on screen
}

function gPregameHtml(a, opp, g, me){
  const lists = [[a, 'This list']].concat(opp && opp !== a ? [[opp, 'Their list']] : []);
  const unitsLine = (L, us, extra) => us.map(u => gLink(L, 'unit', u.id, inArmy(L, () => gUnitName(u))) + (u.copies > 1 ? ' <span class="from">×' + u.copies + '</span>' : '') + (extra ? ' <span class="from">' + esc(extra(u)) + '</span>' : '')).join(', ');
  const per = (fn) => lists.map(([L, label]) => { const t = fn(L); return t ? '<p class="gpl"><span class="il">' + label + '</span>' + t + '</p>' : ''; }).join('');
  const add = {
    7:() => { const line = D.rules['Strategic Reserves'].split('\n').find(l => /50% of your points limit/.test(l));
      return gq(esc('20.01 Placing Units in Strategic Reserves'), line) + per(L => { const ds = gEvery(L, r => inArmy(L, () => ruleKey(r)) === 'Deep Strike');
        const pts = ds.reduce((t, u) => t + (u.pts || 0) * (u.copies || 1), 0);
        return gNote(esc(L.name) + ': points limit ' + L.points + ' pts (' + esc(L.battleSize) + '); 50% of it is ' + Math.floor(L.points / 2) + ' pts.') +
          (ds.length ? '<span class="gpu">Deep Strike: ' + unitsLine(L, ds, u => u.pts + ' pts' + (u.copies > 1 ? ' each, ×' + u.copies : '')) + (ds.length > 1 ? ' <span class="from">(' + pts + ' pts)</span>' : '') + '</span>' : ''); }); },
    8:() => per(L => { const tt = L.units.filter(u => hasKw(u, 'Titanic')), inf = gEvery(L, r => /^infiltrators/i.test(r));
      return [tt.length ? '<span class="gpu">TITANIC: ' + unitsLine(L, tt) + '</span>' : '', inf.length ? '<span class="gpu">' + gLink(L, 'rule', 'Infiltrators', 'Infiltrators') + ': ' + unitsLine(L, inf) + '</span>' : ''].join(''); }),
    10:() => '<div class="chips" role="group" aria-label="Who takes the first turn"><span class="gcg">First turn</span>' + [me, gOther(me)].map(s => { const L = gList(a, s), on = g.first === s;
      return '<button class="chip' + (on ? ' on' : '') + '" data-gset="first|' + s + '" aria-pressed="' + on + '">' + esc(L ? L.name : 'Opponent') + '</button>'; }).join('') + '</div>',
    11:() => per(L => { const sc = gEvery(L, r => /^scouts/i.test(r));
      return sc.length ? '<span class="gpu">' + gLink(L, 'rule', 'Scouts', 'Scouts') + ': ' + unitsLine(L, sc, u => inArmy(L, () => unitRules(u).filter(r => /^scouts/i.test(r)).join(', '))) + '</span>' : ''; })
  };
  const titanic = lists.some(([L]) => L.units.some(u => hasKw(u, 'Titanic'))), infil = lists.some(([L]) => gEvery(L, r => /^infiltrators/i.test(r)).length);
  const scouts = lists.some(([L]) => gEvery(L, r => /^scouts/i.test(r)).length);
  const sub = { 7:'Strategic reserves', 8:[titanic ? 'TITANIC' : '', infil ? 'Infiltrators' : ''].filter(Boolean).join(', '), 10:'Who goes first', 11:scouts ? 'Scouts' : '' };
  return '<p class="note">Warhammer Event Mission Sequence · GW Warhammer Event Companion 1.3</p><div class="abl">' + D.game.sequence.map(([n, title, text]) => {
    const more = add[n] ? add[n]() : '';
    const body = n === 8 && titanic ? rt(text.split('\n').map(l => /\bTITANIC\b/.test(l) ? '- ' + l : l).join('\n')) : rt(text);
    return '<details class="ab rr gseq"><summary><span class="an"><b><span class="gn">' + n + '</span> ' + esc(title) + '</b>' + (sub[n] ? '<span class="rs">' + esc(sub[n]) + '</span>' : '') + '</span>' + chev + '</summary><div class="body">' + body + more + '</div></details>';
  }).join('') + '</div>';
}

function gChoiceHtml(c, g, side, opp){
  const P = gcPick(c, g, side), v = P.v, R = gcRound(c, g);
  const pick = (grp, opt) => esc(JSON.stringify([c.key, R, grp, opt || '']));
  const used = c.once && !c.unit ? new Set(c.groups.flatMap(gr => gr.opts.filter(o => usedSet().has('r:' + c.name + ':' + o.row + '#0')).map(o => o.name))) : new Set();
  const lasts = c.lasts === 'battle' ? 'For the battle' : c.lasts === 'kept' ? 'Until another is picked' : 'Battle round ' + g.round;
  let h = '<div class="gc"><div class="gch">' + linkTo(c.link[0], c.link[1], c.name) + ' <span class="from">· ' + esc(c.src) + '</span></div>' +
    '<p class="gcw">' + esc(c.when) + (c.when ? ' · ' : '') + '<b>' + esc(lasts) + '</b>' + (P.since ? ' <span class="from">(picked in battle round ' + P.since + ')</span>' : '') + '</p>' +
    // a step the Event Companion's mission sequence (Before the battle) does not have, named as the rule names it
    ((m => m && !D.game.sequence.some(([, t]) => norm(t) === norm(m[1])) ? gNote('the Event Companion’s mission sequence (Before the battle, below) has no step called ' + esc(m[1]) + '.') : '')(/\bthe ([A-Z][a-z]+(?: [A-Z][a-z]+)+) step\b/.exec(c.when)));
  for(const gr of c.groups){
    const on = gcNames(v[gr.name]);
    h += '<div class="chips" role="group"' + (gr.name ? ' aria-label="' + esc(gr.name) + '"' : '') + '>' + (gr.name ? '<span class="gcg">' + esc(gr.name) + '</span>' : '') +
      gr.opts.map(o => { const sel = on.includes(o.name), u = !sel && used.has(o.name);
        return '<button class="chip' + (sel ? ' on' : '') + (u ? ' used' : '') + '" data-gpick="' + pick(gr.name, o.name) + '" aria-pressed="' + sel + '">' + esc(o.name) + (u ? '<span class="u">used</span>' : '') + '</button>'; }).join('') +
      (c.rolled ? '<button class="chip rl' + (v['rolled:' + gr.name] ? ' on' : '') + '" data-gpick="' + pick('rolled:' + gr.name) + '" aria-pressed="' + !!v['rolled:' + gr.name] + '">Rolled</button>' : '') + '</div>';
    for(const o of gr.opts.filter(o => on.includes(o.name))){
      h += '<div class="gq gpk"><span class="gqs">' + esc((gr.name ? gr.name + ' ' : '') + o.name + (o.title ? ' · ' + o.title : '')) + '</span>' + rt(o.text) + '</div>';
      const tg = gcTargets(o.text, opp);
      if(tg && tg.length){ const t = v['target:' + gr.name];
        h += '<div class="chips gtg" role="group" aria-label="Their unit"><span class="gcg">Their unit</span>' + tg.map(x => '<button class="chip' + (t === x.id ? ' on' : '') + '" data-gpick="' + pick('target:' + gr.name, x.id) + '" aria-pressed="' + (t === x.id) + '">' + esc(x.name) + '</button>').join('') + '</div>'; }
    }
  }
  if(c.state) h += '<div class="chips"><button class="chip' + (v['state'] ? ' on' : '') + '" data-gpick="' + pick('state') + '" aria-pressed="' + !!v['state'] + '">' + esc(c.state) + '</button></div>';
  // the picks of the other battle rounds of this game
  if(c.lasts !== 'battle'){
    const past = Object.keys(P.all).filter(r => r !== R && +r >= 1).sort((x, y) => x - y).map(r => [r, c.groups.flatMap(gr => gcNames((P.all[r] || {})[gr.name]))]).filter(([, n]) => n.length);
    if(past.length) h += '<p class="gcp">' + past.map(([r, n]) => 'Round ' + r + ': ' + esc(n.join(', '))).join(' · ') + '</p>';
  }
  return h + '</div>';
}

function gamePick(a, spec){
  let k, R, grp, opt;
  try { [k, R, grp, opt] = JSON.parse(spec); } catch(e){ return; }
  const g = gameOf(a), side = gSide(a), c = gameChoices(a).find(x => x.key === k);
  if(!c) return;
  const P = g.picks[side] = isObj(g.picks[side]) ? g.picks[side] : {}, all = P[k] = isObj(P[k]) ? P[k] : {}, v = all[R] = isObj(all[R]) ? all[R] : {};
  if(/^(rolled|target):|^state$/.test(grp)){ const x = opt || true; if(v[grp] === x) delete v[grp]; else v[grp] = x; }
  else {
    const was = gcNames(v[grp]), next = was.includes(opt) ? was.filter(x => x !== opt) : c.max > 1 ? was.concat(opt).slice(-c.max) : [opt];
    if(next.length) v[grp] = c.max > 1 ? next : next[0]; else delete v[grp];
    if(!next.includes(opt) || c.max === 1) delete v['target:' + grp];   // another option: its unit is picked again
    const gr = c.groups.find(x => x.name === grp);
    if(c.once && gr){ const used = usedSet();
      for(const o of gr.opts){ const tk = 'r:' + c.name + ':' + o.row + '#0', other = Object.entries(all).some(([r, x]) => r !== R && gcNames((x || {})[grp]).includes(o.name));
        if(next.includes(o.name)) used.add(tk); else if(was.includes(o.name) && !other) used.delete(tk); }
      store.set(usedKey(), [...used]); }
  }
  if(!Object.keys(v).length) delete all[R];
  gameSave(a, g);
}
